resultado = []
for t in trabajos:
    if t["estado"] == "ejecutando":
        resultado.append(dict(id=t["id"], estado="ejecutando", prioridad="normal"))
    elif es_limite:
        resultado.append(dict(id=t["id"], estado="en espera de tiempo", prioridad="normal"))
    else:
        resultado.append(dict(id=t["id"], estado="en cola", prioridad="baja"))
return resultado
